// Proves the axios FormData fix against the LIVE API.
// A) instance without a global JSON content-type  -> expect 200 + S3 URL
// B) instance WITH "Content-Type: application/json" (the old bug)
//    -> expect 400 "The submitted data was not a file"
import axios from "axios";
import { readFileSync } from "node:fs";

const { token, username } = JSON.parse(readFileSync("node_token.txt", "utf8"));
const API = "http://127.0.0.1:8000/api";

// Real PNG generated by Pillow (guaranteed valid for DRF ImageField/PIL)
const png = readFileSync("probe.png");

const fd = new FormData();
fd.append("profile_image", new Blob([png], { type: "image/png" }), "probe.png");

// A) fixed instance (no default content-type) — mirrors services/api.ts after fix
const good = axios.create({ baseURL: API });
try {
  const response = await good.put("/influencer/profile/", fd, {
    headers: { Authorization: `Bearer ${token}` },
  });
  console.log("A) FIXED  ->", response.status, "|", response.data.profile_image);
} catch (error) {
  console.log("A) FIXED  -> FAIL", error.response?.status, JSON.stringify(error.response?.data));
}

// B) old buggy instance (global application/json) — reproduces the user's 400
const bad = axios.create({ baseURL: API, headers: { "Content-Type": "application/json" } });
try {
  const response = await bad.put("/influencer/profile/", fd, {
    headers: { Authorization: `Bearer ${token}` },
  });
  console.log("B) BUGGY  ->", response.status, "(unexpected pass)");
} catch (error) {
  console.log("B) BUGGY  ->", error.response?.status, "|", JSON.stringify(error.response?.data));
}

console.log("cleanup username:", username);
